def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # Find the solid divider nearest the center, avoiding incidental
    # all-one-color rows or columns elsewhere in the panels.
    candidates = []
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            candidates.append((abs(c - (w - 1) / 2), "v", c))
    for r in range(h):
        if all(x == grid[r][0] for x in grid[r]):
            candidates.append((abs(r - (h - 1) / 2), "h", r))
    _, orient, divider = min(candidates)

    if orient == "v":
        a = [row[:divider] for row in grid]
        b = [row[divider + 1:] for row in grid]
        n = min(len(a[0]), len(b[0]))
        a = [row[:n] for row in a]
        b = [row[:n] for row in b]
    else:
        n = min(divider, h - divider - 1)
        a, b = grid[:n], grid[divider + 1:divider + 1 + n]

    def colors(panel):
        counts = Counter(x for row in panel for x in row)
        ordered = counts.most_common()
        bg = ordered[0][0]
        fg = ordered[1][0] if len(ordered) > 1 else bg
        return bg, fg

    bg_a, fg_a = colors(a)
    bg_b, fg_b = colors(b)

    if bg_a == bg_b:
        return [
            [bg_a if (a[r][c] != bg_a or b[r][c] != bg_b) else 3
             for c in range(len(a[r]))]
            for r in range(n)
        ]

    if fg_a == fg_b:
        return [
            [3 if a[r][c] == fg_a and b[r][c] == fg_b else fg_a
             for c in range(len(a[r]))]
            for r in range(n)
        ]

    if fg_a == bg_b:
        return [
            [3 if a[r][c] == fg_a else bg_b for c in range(len(a[r]))]
            for r in range(n)
        ]

    if fg_b == bg_a:
        return [
            [3 if b[r][c] == fg_b else bg_a for c in range(len(a[r]))]
            for r in range(n)
        ]

    return [
        [3 if a[r][c] != bg_a or b[r][c] != bg_b else bg_a
         for c in range(len(a[r]))]
        for r in range(n)
    ]
